/* Alternative 3 */
static int fpr_lt(uint64_t x, uint64_t y) {
    int sx = (int)(x >> 63);
    int sy = (int)(y >> 63);

    return (sx && !sy)
        || (!sx && !sy && x < y)
        || (sx && sy && x > y);
}
