static int fpr_lt(uint64_t x, uint64_t y) {
    int sx = (int)(x >> 63);
    int different = (int)((x ^ y) >> 63);
    int same_result = ((x < y) ^ sx) & (x != y);

    return (different & sx) | ((different ^ 1) & same_result);
